import * as Handlebars from 'handlebars';
Handlebars.registerHelper('equals', function helper(arg1, arg2, options) {
    return arg1 == arg2 ? options.fn(this) : options.inverse(this);
});
export class HandlebarsContentEngine {
    compileTemplate(content, payload) {
        const template = Handlebars.compile(content);
        return template(payload);
    }
    extractMessageVariables(content) {
        return getHandlebarsVariables(content);
    }
}
function getHandlebarsVariables(input) {
    const ast = Handlebars.parseWithoutProcessing(input);
    return ast.body
        .filter(({ type }) => type === 'MustacheStatement')
        .map((statement) => {
        const moustacheStatement = statement;
        const paramsExpressionList = moustacheStatement.params;
        const pathExpression = moustacheStatement.path;
        return paramsExpressionList[0]?.original || pathExpression.original;
    });
}
